import numpy as np
def read(p):
    L=open(p).read().split('\n'); n=int(L[0]); ats=[]; xyz=[]
    for line in L[2:2+n]:
        f=line.split(); ats.append(f[0]); xyz.append([float(x) for x in f[1:4]])
    return ats, np.array(xyz)
a,P = read('opt1.xyz')
n=len(a)
pairs=[]
for i in range(n):
    for j in range(i+1,n):
        dd=np.linalg.norm(P[i]-P[j])
        pairs.append((dd,i,j))
pairs.sort()
for dd,i,j in pairs[:12]:
    print("%.2f %s%d %s%d"%(dd,a[i],i,a[j],j))
